  'holo.lede': ['Rotating LED hologram fans are pseudo-volumetric displays: the background must be pure black, the subject must stay inside the safe area, and small text simply will not resolve. The studio checks all of this automatically and converts ordinary artwork into device-compatible animation.',
    '旋轉式 LED 全息風扇屬偽體積顯示：背景必須純黑、主體須留在安全區域，細小文字無法呈現。創作室會自動檢查並將一般素材轉換為裝置相容動畫。',
    '旋转式 LED 全息风扇属伪体积显示：背景必须纯黑、主体须留在安全区域，细小文字无法呈现。创作室会自动检查并将一般素材转换为设备兼容动画。'],
  'holo.r1': ['Pure black background (#000000)', '純黑背景（#000000）', '纯黑背景（#000000）'],
