  'docs.i2_d': ['Mall, clinic, restaurant, office, transport and so on — drives the price multiplier.', '商場、診所、餐廳、辦公室、交通樞紐等 — 決定價格乘數。', '商场、诊所、餐厅、办公室、交通枢纽等 — 决定价格乘数。'],
