  'docs.h4_v': ['Against the device profile', '對照裝置設定檔', '对照设备配置文件'],
  'docs.h5': ['File size and loop duration', '檔案大小及循環時長', '文件大小及循环时长'],
  'docs.h5_v': ['Transfer reliability', '傳輸可靠性', '传输可靠性'],
  'docs.h6': ['Small-text warning', '細小文字警示', '细小文字警示'],
  'docs.h6_v': ['Operator review', '營運審核', '运营审核'],
  'docs.h7': ['Rotation suitability', '旋轉適用性', '旋转适用性'],
  'docs.h7_v': ['Manufacturer guidance', '製造商指引', '制造商指引'],
  'docs.device_note': ['Rotating LED fans are pseudo-volumetric: black pixels emit no light, so a black background is what produces the floating image. Small text will not resolve, white backgrounds destroy the illusion, and the fan needs 8–10 hours of running followed by roughly 30 minutes of rest with at least 30 cm of clearance.',
    '旋轉式 LED 風扇屬偽體積顯示：黑色像素不發光，因此純黑背景才會產生懸浮影像。細小文字無法呈現，白色背景會破壞錯覺；風扇需連續運轉 8–10 小時後休息約 30 分鐘，並預留至少 30 公分距離。',
    '旋转式 LED 风扇属伪体积显示：黑色像素不发光，因此纯黑背景才会产生悬浮影像。细小文字无法呈现，白色背景会破坏错觉；风扇需连续运行 8–10 小时后休息约 30 分钟，并预留至少 30 厘米距离。'],
  'docs.roadmap': ['7. Roadmap and scope discipline', '7. 路線圖與範圍紀律', '7. 路线图与范围纪律'],
  'docs.col_phase': ['Phase', '階段', '阶段'],
  'docs.col_scope': ['Scope', '範圍', '范围'],
  'docs.col_locations': ['Locations', '場地數目', '场地数量'],
  'docs.loc_1': ['10–30', '10–30', '10–30'],
  'docs.loc_2': ['50–300', '50–300', '50–300'],
  'docs.loc_3': ['300+', '300+', '300+'],
  'docs.compliance': ['8. Compliance, privacy and content policy', '8. 合規、私隱及內容政策', '8. 合规、隐私及内容政策'],
  'docs.cmp1': ['Regulated categories (medical claims, financial products, tobacco/vaping, alcohol, gambling) require evidence of approval and venue consent before scheduling.',
    '受規管類別（醫療聲稱、金融產品、煙草／電子煙、酒精、博彩）在排程前須提供批准證明及場地同意。',
    '受监管类别（医疗声称、金融产品、烟草／电子烟、酒精、博彩）在排程前须提供批准证明及场地同意。'],
  'docs.cmp2': ['Every creative must be lawful, cleared for third-party rights (music, fonts, likeness, trademarks) and consistent with venue restrictions.',
    '所有素材必須合法、已取得第三方權利（音樂、字體、肖像、商標），並符合場地限制。',
    '所有素材必须合法、已取得第三方权利（音乐、字体、肖像、商标），并符合场地限制。'],
  'docs.cmp3': ['QR and NFC landing pages that collect personal data must publish a collection-purpose statement and follow the Personal Data (Privacy) Ordinance in Hong Kong; coupon data is stored pseudonymously.',
    '收集個人資料的二維碼及 NFC 著陸頁須發佈收集目的聲明，並遵守香港《個人資料（私隱）條例》；優惠券資料以假名方式儲存。',
    '收集个人数据的二维码及 NFC 落地页须发布收集目的声明，并遵守香港《个人资料（隐私）条例》；优惠券数据以假名方式存储。'],
  'docs.cmp4': ['Noise, light spill and operating-hour rules are enforced by the scheduler, including mandatory rest periods and dimming at night.',
    '聲量、光害及營業時間規則由排程系統執行，包括強制休息時段及夜間調暗。',
    '音量、光污染及营业时间规则由排程系统执行，包括强制休息时段及夜间调暗。'],
  'docs.cmp5': ['AI-generated advertising is disclosed to the operator during moderation, and AI assets keep a prompt and model audit trail.',
    'AI 生成廣告會在審核時向營運方披露，AI 素材保留提示及模型審計紀錄。',
    'AI 生成广告会在审核时向运营方披露，AI 素材保留提示及模型审计记录。'],
  'docs.cmp6': ['People-counting, if ever deployed, stays on-device, keeps no images and no identifiers, and is disclosed at the venue.',
    '如日後採用客流計數，必須在裝置端處理、不保留影像及識別資料，並在場地作出披露。',
    '如日后采用客流计数，必须在设备端处理、不保留影像及识别信息，并在场地作出披露。'],
  'docs.cta_title': ['See the transaction end to end', '完整體驗整宗交易', '完整体验整笔交易'],
  'docs.cta_lede': ['Book a location, generate the creative, pay in the simulated gateway and read the proof-of-play report.',
    '預訂場地、生成素材、在模擬支付閘道付款，然後閱讀播放證明報告。',
    '预订场地、生成素材、在模拟支付网关付款，然后阅读播放证明报告。'],

