  'nav.video': ['Explainer', '介紹影片', '介绍视频'],
  'video.eyebrow': ['Explainer video', '介紹影片', '介绍视频'],
  'video.title': ['Two sides, one transaction: how advertisers and landlords both win', '兩方共贏：廣告客戶與場地擁有人如何同時得益', '两方共赢：广告客户与场地拥有人如何同时得益'],
  'video.lede': ['A 146-second, 11-chapter walkthrough of the marketplace — what a DSP does, what an online ad platform gives an advertiser, what a location owner gets, how location-based services pull and push, and the pipeline that connects them. Narrated and subtitled in English, Traditional Chinese and Simplified Chinese.',
    '146 秒、11 章的平台導覽 — DSP 的作用、線上廣告平台為廣告客戶帶來什麼、場地擁有人得到什麼、位置服務如何拉取與推送，以及連接雙方的流程。備有英文、繁體中文及簡體中文旁白與字幕。',
    '146 秒、11 章的平台导览 — DSP 的作用、在线广告平台为广告客户带来什么、场地拥有人得到什么、位置服务如何拉取与推送，以及连接双方的流程。备有英文、繁体中文及简体中文旁白与字幕。'],
  'video.meta_length': ['146 seconds', '146 秒', '146 秒'],
