  'video.ctx_title': ['DSPs, ad platforms and where 3dNakedEye fits', 'DSP、廣告平台，以及 3dNakedEye 的定位', 'DSP、广告平台，以及 3dNakedEye 的定位'],
  'video.ctx_lede': ['The explainer sits inside a wider programmatic market. These three cards are the context a brand or a landlord usually asks about, in the same order the video covers them.',
    '介紹影片建立在更廣闊的程序化市場之上。以下三張卡片就是品牌或場地擁有人通常會問的背景，次序與影片一致。',
    '介绍视频建立在更广阔的程序化市场之上。以下三张卡片就是品牌或场地拥有人通常会问的背景，次序与视频一致。'],
