  'video.dsp_body': ['A demand-side platform is the buying cockpit: an advertiser or agency sets budget, audience and goals, and the DSP decides which impressions to buy across many publishers and formats — display, video, CTV, audio and digital out-of-home. The Trade Desk is the reference independent DSP: it does not own inventory, so optimisation is not tilted towards its own media.',
    '需求方平台是購買中樞：廣告客戶或代理商設定預算、受眾及目標，DSP 決定在眾多發行商及格式（展示、影片、聯網電視、音訊、戶外數位）中購買哪些曝光。The Trade Desk 是獨立 DSP 的參考案例：不擁有庫存，因此優化不會偏向自家媒體。',
    '需求方平台是购买中枢：广告客户或代理商设定预算、受众及目标，DSP 决定在众多发布商及格式（展示、视频、联网电视、音频、户外数字）中购买哪些曝光。The Trade Desk 是独立 DSP 的参考案例：不拥有库存，因此优化不会偏向自家媒体。'],
