  'ads.planner_none': ['No match — try a broader term such as "mall" or "clinic".', '沒有符合結果 — 請嘗試更廣泛的詞，例如「商場」或「診所」。', '没有匹配结果 — 请尝试更宽泛的词，例如“商场”或“诊所”。'],
