  'docs.f1_d': ['The basket is priced with the provider fee for the chosen method, before the advertiser commits.', '購物車會按所選方式的服務商手續費計價，然後廣告客戶才確認。', '购物车会按所选方式的服务商手续费计价，然后广告客户才确认。'],
