  'docs.f2_d': ['The server creates a Stripe PaymentIntent, PayPal order or crypto invoice; keys never reach the browser.', '伺服器建立 Stripe PaymentIntent、PayPal 訂單或加密貨幣發票；金鑰不會傳到瀏覽器。', '服务器创建 Stripe PaymentIntent、PayPal 订单或加密货币发票；密钥不会传到浏览器。'],
