  'docs.r3_v': ['15 minutes + buffer', '15 分鐘 + 緩衝', '15 分钟 + 缓冲'],
  'docs.r4': ['Refunds', '退款', '退款'],
  'docs.r4_v': ['Full media refund if rejected', '被拒即全額退回媒體費', '被拒即全额退回媒体费'],
  'docs.pay_note': ['Crypto is quoted in coin units with a short rate lock and a volatility buffer, then settled to HKD on confirmation so landlord payouts stay in one currency. Card data never reaches 3dNakedEye servers: Stripe collects it and returns a PaymentIntent.',
    '加密貨幣以幣種單位報價，設有短時間匯率鎖定及波動緩衝，確認後兌換為港幣，讓場地撥款維持單一貨幣。卡資料不會到達 3dNakedEye 伺服器：由 Stripe 收集並回傳 PaymentIntent。',
    '加密货币以币种单位报价，设有短时间汇率锁定及波动缓冲，确认后兑换为港币，让场地拨款维持单一货币。卡数据不会到达 3dNakedEye 服务器：由 Stripe 收集并返回 PaymentIntent。'],
  'docs.vid': ['11. Explainer video and localisation', '11. 介紹影片與本地化', '11. 介绍视频与本地化'],
  'docs.vid_body': ['The explainer is an animated, chaptered player with narration and subtitles in every built-in language, so one asset serves an advertiser pitch, a landlord pitch and a sales deck. It can be replaced by your own footage without touching the rest of the site.',
    '介紹影片是一個具章節的動畫播放器，旁白及字幕支援所有內建語言，因此同一素材可用於廣告客戶提案、場地提案及銷售簡報。你亦可換成自己的影片，而不影響網站其他部分。',
    '介绍视频是一个有章节的动画播放器，旁白及字幕支持所有内置语言，因此同一素材可用于广告客户提案、场地提案及销售简报。你也可换成自己的视频，而不影响网站其他部分。'],
  'docs.vid_swap': ['Publishing your own video', '發佈你自己的影片', '发布你自己的视频'],
