  'chat.launch': ['Ask 3dNakedEye', '問 3dNakedEye', '问 3dNakedEye', 'ถาม 3dNakedEye'],
  'chat.title': ['3dNakedEye Assistant', '3dNakedEye 智能助理', '3dNakedEye 智能助理', 'ผู้ช่วย 3dNakedEye'],
  'chat.sub': ['Instant answers about hologram fans, pricing, booking and accounts', '全息風扇、價格、預訂及帳戶的即時解答', '全息风扇、价格、预订及账户的即时解答', 'ตอบทันทีเรื่องพัดลมโฮโลแกรม ราคา การจอง และบัญชี'],
  'chat.greeting': ['Hi — I am the 3dNakedEye assistant. Ask me about the hologram fans, how booking works, pricing, landlords or your account. I answer from the FAQ knowledge base; if I do not know, I will hand you to the team on WhatsApp.',
    '你好，我是 3dNakedEye 智能助理。可以問我有關全息風扇、預訂流程、價格、場地或帳戶的問題。我根據常見問題知識庫作答；不知道的，我會把你的問題轉交 WhatsApp 真人團隊。',
    '你好，我是 3dNakedEye 智能助理。可以问我有关全息风扇、预订流程、价格、场地或账户的问题。我根据常见问题知识库作答；不知道的，我会把你的问题转交 WhatsApp 真人团队。',
    'สวัสดี ฉันคือผู้ช่วย 3dNakedEye ถามได้เรื่องพัดลมโฮโลแกรม ขั้นตอนการจอง ราคา เจ้าของสถานที่ หรือบัญชีของคุณ ฉันตอบจากฐานความรู้คำถามที่พบบ่อย หากไม่รู้จะส่งต่อให้ทีมทาง WhatsApp'],
