  'docs.data_title': ['18. Catalogue, dimensions and the cloud walkthrough', '18. 產品目錄、尺寸計算與雲端操作', '18. 产品目录、尺寸计算与云端操作', '18. แคตตาล็อก การคำนวณขนาด และคู่มือคลาวด์'],
  'docs.data_body': ['The catalogue, the calculator and the cloud walkthrough are transcribed from the supplier’s own documents. Nothing is estimated: where a document is silent the page says so.', '產品目錄、尺寸計算器與雲端操作教學，全部轉錄自供應商文件。我們不做估算——文件未列出的，頁面會明說。', '产品目录、尺寸计算器与云端操作教程，全部转录自供应商文件。我们不做估算——文件未列出的，页面会明说。', 'แคตตาล็อก เครื่องคำนวณขนาด และคู่มือคลาวด์ ถอดความจากเอกสารของผู้ผลิตโดยตรง ไม่มีการประมาณค่า จุดใดที่เอกสารไม่ระบุ หน้าเว็บจะบอกไว้'],
