  'enq.device_holo_box': ['Holobox cabinet', 'Holobox 機櫃', 'Holobox 机柜', 'ตู้ Holobox'],
  'hb.eyebrow': ['Life-size hologram display', '真人比例全息顯示', '真人比例全息显示', 'จอโฮโลแกรมขนาดเท่าตัวจริง'],
  'hb.title': ['Holobox: a person, standing in the room', 'Holobox：真人就站在眼前', 'Holobox：真人就站在眼前', 'Holobox: บุคคลที่ยืนอยู่ในห้องจริง'],
  'hb.lede': ['A transparent LCD panel sits in front of a custom-engineered, highly illuminated light box. That stack is what produces genuine optical depth: the person looks solid and life-size, with no smoke, no projection rig and no headset.', '透明 LCD 面板置於特製高亮燈箱之前，這個組合產生真正的光學縱深：人物立體、真人比例，不用煙幕、不用投影機組、不用頭戴裝置。', '透明 LCD 面板置于特制高亮灯箱之前，这个组合产生真正的光学纵深：人物立体、真人比例，不用烟雾、不用投影机组、不用头戴设备。', 'แผ่น LCD โปร่งใสวางอยู่หน้าไลต์บ็อกซ์ที่ออกแบบเฉพาะและให้แสงสว่างสูง ชุดนี้สร้างความลึกทางแสงจริง บุคคลจึงดูเป็นตัวตนขนาดเท่าจริง โดยไม่ต้องใช้ควัน ไม่ต้องตั้งชุดโปรเจกเตอร์ และไม่ต้องสวมแว่น'],
  'hb.lede_short': ['A life-size person, live or recorded, inside a cabinet that needs only power and internet.', '真人比例的人物，即時或預錄，放進只需電源與網路的機櫃。', '真人比例的人物，实时或预录，放进只需电源与网络的机柜。', 'บุคคลขนาดเท่าตัวจริง สดหรือบันทึกไว้ ในตู้ที่ต้องการเพียงไฟและอินเทอร์เน็ต'],
  'hb.stat1': ['Panel', '面板', '面板', 'แผง'],
