  'hb.b1_lede': ['Not a projection: a light box, a diffuser and a transparent panel, layered in that order. The eye reads the gap between the layers as depth.', '不是投影：燈箱、擴散板與透明面板依序疊放，眼睛把層與層之間的距離讀成縱深。', '不是投影：灯箱、扩散板与透明面板依序叠放，眼睛把层与层之间的距离读成纵深。', 'ไม่ใช่การฉายภาพ: ไลต์บ็อกซ์ แผ่นกระจายแสง และแผงโปร่งใส เรียงซ้อนกันตามลำดับ สายตาจะอ่านช่องว่างระหว่างชั้นเป็นความลึก'],
  'hb.b1_cap': ['The optical stack, drawn to scale. Press play to watch which layer the eye locks onto.', '依比例繪製的光學堆疊。按播放，看眼睛鎖定哪一層。', '依比例绘制的光学堆叠。按播放，看眼睛锁定哪一层。', 'ชุดชั้นแสงตามสัดส่วน กดเล่นเพื่อดูว่าสายตาจับที่ชั้นใด'],
