  'hb.player_note': ['Built-in explainer: it is drawn in your browser, so no third-party footage is loaded and nothing is uploaded.', '內建解說：在你的瀏覽器中直接繪製，不載入任何第三方影片，也不上傳任何檔案。', '内置讲解：在你的浏览器中直接绘制，不加载任何第三方视频，也不上传任何文件。', 'คำอธิบายในตัว: วาดขึ้นในเบราว์เซอร์ของคุณ ไม่โหลดวิดีโอของบุคคลที่สาม และไม่มีการอัปโหลดไฟล์ใด'],
  'hb.b2': ['Three ways to appear', '三種出場方式', '三种出场方式', 'สามวิธีในการปรากฏตัว'],
  'hb.b2_lede': ['The same cabinet, three different sources for the person inside it.', '同一個機櫃，裡面的人物可以來自三個不同來源。', '同一个机柜，里面的人物可以来自三个不同来源。', 'ตู้เดียวกัน แต่แหล่งที่มาของบุคคลข้างในมีสามแบบ'],
  'hb.l1': ['Pre-recorded clip', '預錄影片', '预录视频', 'คลิปที่บันทึกไว้'],
  'hb.l1_d': ['A produced film loops on the panel. The unit works unattended, all day, in one language or thirty.', '製作好的影片在面板上循環播放，無人值守也能全天運作，一種語言或三十種語言都行。', '制作好的视频在面板上循环播放，无人值守也能全天运作，一种语言或三十种语言都行。', 'ภาพยนตร์ที่ผลิตไว้เล่นวนบนแผง ทำงานได้เองตลอดวัน ทั้งในภาษาเดียวหรือสามสิบภาษา'],
  'hb.l2': ['Live 4K two-way', '4K 即時雙向', '4K 实时双向', '4K สองทางแบบสด'],
  'hb.l2_d': ['An integrated camera and microphone turn it into a conversation rather than a broadcast: the visitor is seen and heard on the other side.', '內建鏡頭與麥克風讓它成為對話而非單向廣播：對方看得到、也聽得到現場的訪客。', '内置摄像头与麦克风让它成为对话而非单向广播：对方看得到、也听得到现场的访客。', 'กล้องและไมโครโฟนในตัวทำให้เป็นการสนทนา ไม่ใช่การออกอากาศฝ่ายเดียว อีกฝั่งเห็นและได้ยินผู้มาเยือน'],
  'hb.l3': ['AI metahuman avatar', 'AI 虛擬人物分身', 'AI 虚拟人物分身', 'อวตาร AI'],
  'hb.l3_d': ['A trained avatar answers from your own knowledge base, in the visitor’s language, and hands over to a human when the question leaves its scope.', '受訓過的分身依你的知識庫回答，使用訪客的語言；問題超出範圍時會轉交真人。', '受训过的分身依你的知识库回答，使用访客的语言；问题超出范围时会转交真人。', 'อวตารที่ฝึกไว้ตอบจากฐานความรู้ของคุณ ในภาษาของผู้มาเยือน และส่งต่อให้เจ้าหน้าที่เมื่อคำถามเกินขอบเขต'],
  'hb.b3': ['Plug and play, stated honestly', '即插即用，實話實說', '即插即用，实话实说', 'plug and play ตามความเป็นจริง'],
  'hb.b3_lede': ['Two connections, no rigging and no dark room.', '兩個接頭，不用搭建，也不用暗房。', '两个接头，不用搭建，也不用暗房。', 'สองจุดเชื่อมต่อ ไม่ต้องตั้งโครง ไม่ต้องห้องมืด'],
  'hb.p1': ['Power: a standard socket. There is no smoke, no projector and no headset anywhere in the chain.', '電源：一般插座。整條鏈路沒有煙幕、沒有投影機、沒有頭戴裝置。', '电源：普通插座。整条链路没有烟雾、没有投影机、没有头戴设备。', 'ไฟ: ปลั๊กมาตรฐาน ทั้งระบบไม่มีควัน ไม่มีโปรเจกเตอร์ และไม่มีแว่น'],
  'hb.p2': ['Network: Wi-Fi, LAN or 4G/5G — whatever the venue already has, for a live link.', '網路：Wi-Fi、LAN 或 4G/5G，直播用場地現有的連線即可。', '网络：Wi-Fi、LAN 或 4G/5G，直播用场地现有的连接即可。', 'เครือข่าย: Wi-Fi, LAN หรือ 4G/5G ใช้อะไรที่มีอยู่แล้วในสถานที่สำหรับลิงก์สด'],
  'hb.p3': ['Daylight: anti-glare front glass keeps the image readable in a lit lobby, not only in a dark room.', '日光：防眩玻璃讓影像在有光的大堂也看得清，不只限於暗房。', '日光：防眩玻璃让影像在有光的大堂也看得清，不限于暗房。', 'แสงกลางวัน: กระจกกันสะท้อนทำให้ภาพชัดในล็อบบี้ที่มีแสง ไม่ใช่แค่ในห้องมืด'],
  'hb.p4': ['Interaction: a 20-point touch panel, a hand-held remote, or none at all if the clip already tells the story.', '互動：20 點觸控面板、手持遙控；如果影片本身已說完整個故事，也可以完全不互動。', '交互：20 点触摸面板、手持遥控；如果视频本身已说完整故事，也可以完全不交互。', 'การโต้ตอบ: จอสัมผัส 20 จุด รีโมตในมือ หรือไม่ต้องโต้ตอบเลยหากคลิปเล่าเรื่องครบแล้ว'],
  'hb.p5': ['Service: we install it, we shoot the content, and we stay reachable on WhatsApp and LINE afterwards.', '服務：我們安裝、我們拍攝內容，之後也持續在 WhatsApp 與 LINE 上回覆你。', '服务：我们安装、我们拍摄内容，之后也持续在 WhatsApp 与 LINE 上回复你。', 'บริการ: เราติดตั้ง เราถ่ายทำคอนเทนต์ และติดต่อเราได้ทาง WhatsApp และ LINE หลังจากนั้น'],
