  'hb.b4_lede': ['Six deployments we quote most often. The cabinet is the same; the person inside changes.', '我們最常報價的六種場景。機櫃相同，裡面的人不同。', '我们最常报价的六种场景。机柜相同，里面的人不同。', 'หกการใช้งานที่เราประเมินบ่อยที่สุด ตัวตู้เหมือนกัน แต่คนข้างในเปลี่ยนไป'],
