  'cat.a13_p': ['Brushless motor rated 100,000 hours MTBF, 45 dB and 85 % energy efficiency', '無刷電機平均無故障時間 100,000 小時，45 分貝，能源效率 85%', '无刷电机平均无故障时间 100,000 小时，45 分贝，能源效率 85%', 'มอเตอร์ไร้แปรงถ่าน MTBF 100,000 ชั่วโมง 45 เดซิเบล ประสิทธิภาพพลังงาน 85%'],
