  'cat.f_lightbox': ['Double-sided signage', '雙面招牌', '双面招牌', 'ป้ายสองหน้า'],
  'cat.f_lightbox_d': ['A lit box with a fan inside, readable from both sides — shopfronts and chain stores.', '內置風扇的發光箱體，兩面都能看見——店門與連鎖店。', '内置风扇的发光箱体，两面都能看见——店门与连锁店。', 'กล่องมีไฟพร้อมพัดลมด้านใน มองเห็นได้สองด้าน — หน้าร้านและร้านเชน'],
  'cat.f_hdmi': ['Real-time HDMI', '即時 HDMI', '实时 HDMI', 'HDMI เรียลไทม์'],
  'cat.f_hdmi_d': ['Live input instead of stored files: cameras, PCs and stage feeds.', '以即時輸入取代儲存檔案：攝影機、電腦與舞台訊號。', '以实时输入取代存储文件：摄像头、电脑与舞台信号。', 'รับสัญญาณสดแทนไฟล์ที่เก็บไว้: กล้อง คอมพิวเตอร์ และฟีดจากเวที'],
