  'cat.m_3wall': ['4 m² wall frame (3×3)', '4 平方公尺壁掛框架（3×3）', '4 平方米壁挂框架（3×3）', 'โครงยึดผนัง 4 ตร.ม. (3×3)'],
  'cat.m_3wall_u': ['65 cm × 9 · wall-mounted', '65 公分 × 9 · 壁掛', '65 厘米 × 9 · 壁挂', '65 ซม. × 9 · ยึดผนัง'],
  'cat.m_3floor': ['4 m² floor frame (3×3)', '4 平方公尺落地框架（3×3）', '4 平方米落地框架（3×3）', 'โครงตั้งพื้น 4 ตร.ม. (3×3)'],
  'cat.m_3floor_u': ['65 cm × 9 · floor-mounted', '65 公分 × 9 · 落地', '65 厘米 × 9 · 落地', '65 ซม. × 9 · ตั้งพื้น'],
