  'cat.acc_rshape': ['R-shaped cabinet', 'R 型機櫃', 'R 型机柜', 'ตู้ทรง R'],
  'cat.acc_rshape_n': ['65 cm class · 155.3 cm tall, cover 69×69×12 cm, chassis 45×45 cm', '65 公分級 · 高 155.3 公分，上蓋 69×69×12 公分，底座 45×45 公分', '65 厘米级 · 高 155.3 厘米，上盖 69×69×12 厘米，底座 45×45 厘米', 'ระดับ 65 ซม. · สูง 155.3 ซม. ฝาครอบ 69×69×12 ซม. ฐาน 45×45 ซม.'],
  'cat.acc_stand': ['Floor stand', '落地支架', '落地支架', 'ขาตั้งพื้น'],
  'cat.acc_stand_n': ['91×12.5×12.5 cm · 1.88 kg; a 150/180 cm version adds a 1–1.6 m column', '91×12.5×12.5 公分 · 1.88 公斤；150／180 公分版本另加 1–1.6 公尺立柱', '91×12.5×12.5 厘米 · 1.88 公斤；150／180 厘米版本另加 1–1.6 米立柱', '91×12.5×12.5 ซม. · 1.88 กก. รุ่น 150/180 ซม. เพิ่มเสาสูง 1–1.6 ม.'],
  'cat.acc_hanger': ['Hanger (75 cm)', '吊掛件（75 公分）', '吊挂件（75 厘米）', 'ชุดแขวน (75 ซม.)'],
  'cat.acc_hanger_n': ['Box 19×7×4 cm, rod 55 cm, packed 56×10×10 cm', '外盒 19×7×4 公分，吊桿 55 公分，包裝 56×10×10 公分', '外盒 19×7×4 厘米，吊杆 55 厘米，包装 56×10×10 厘米', 'กล่อง 19×7×4 ซม. เสาแขวน 55 ซม. บรรจุ 56×10×10 ซม.'],
  'cat.acc_wallbox': ['Wall-mounted box (150 cm)', '壁掛箱（150 公分）', '壁挂箱（150 厘米）', 'กล่องยึดผนัง (150 ซม.)'],
  'cat.acc_wallbox_n': ['Metal frame for the 150 cm units, floor-standing version on request', '150 公分型號用金屬框架，可另訂落地版本', '150 厘米型号用金属框架，可另订落地版本', 'โครงโลหะสำหรับรุ่น 150 ซม. มีรุ่นตั้งพื้นตามสั่ง'],
  'cat.source_note': ['Specifications come from the manufacturer’s catalogue and price list. Where the two documents disagree, the newer price list is published, and a figure neither of them states stays a dash.', '規格來自製造商的目錄與價格表。兩份文件不一致時，採用較新的價格表；兩者都沒有列出的數值，以「—」表示。', '规格来自制造商的目录与价格表。两份文件不一致时，采用较新的价格表；两者都没有列出的数值，以「—」表示。', 'สเปกมาจากแคตตาล็อกและใบราคาของผู้ผลิต หากสองเอกสารไม่ตรงกัน จะใช้ฉบับใบราคาที่ใหม่กว่า และค่าที่ทั้งสองฉบับไม่ระบุจะแสดงเป็น “—”'],
  'pl.eyebrow': ['Hong Kong price list', '香港價格表', '香港价格表', 'รายการราคาฮ่องกง'],
  'pl.title': ['Every model, in Hong Kong dollars', '所有型號，港幣報價', '所有型号，港币报价', 'ทุกรุ่น ในสกุลเงินดอลลาร์ฮ่องกง'],
  'pl.lede': ['The line sheet for 1 March – 30 June 2026: 23 models across five series, plus the cabinets, light boxes, frames and covers that go around them. Hardware prices are our suggested retail in Hong Kong; accessories are quoted ex-crate.', '2026 年 3 月 1 日至 6 月 30 日的產品線表：五個系列共 23 款型號，以及搭配的機櫃、燈箱、框架與保護罩。硬件為香港建議零售價；配件報價不含木箱。', '2026 年 3 月 1 日至 6 月 30 日的产品线表：五个系列共 23 款型号，以及搭配的机柜、灯箱、框架与保护罩。硬件为香港建议零售价；配件报价不含木箱。', 'รายการสินค้าสำหรับ 1 มีนาคม – 30 มิถุนายน 2026: 23 รุ่นในห้าซีรีส์ พร้อมตู้ ไลต์บ็อกซ์ กรอบ และฝาครอบ ราคาเครื่องเป็นราคาแนะนำในฮ่องกง ส่วนอุปกรณ์เสริมไม่รวมกล่องไม้'],
  'pl.valid': ['Valid {from} – {to}', '有效期 {from} 至 {to}', '有效期 {from} 至 {to}', 'ใช้ได้ {from} – {to}'],
