  'sz.stat_units': ['Units in the table', '表內台數', '表内台数', 'จำนวนเครื่องในตาราง'],
  'sz.stat_max': ['Widest row in the table', '表內最寬一排', '表内最宽一排', 'แถวกว้างสุดในตาราง'],
  'sz.models': ['The models this page answers for', '本頁涵蓋的型號', '本页涵盖的型号', 'รุ่นที่หน้านี้ตอบให้'],
  'sz.models_lede': ['The sheet prints size classes, not model names, so each model is shown against the class whose display size matches it. A80 and A300 are the outdoor waterproof units.', '表格印的是尺寸級別而非型號名稱，因此每個型號對應到顯示尺寸相符的級別。A80 與 A300 為戶外防水機型。', '表格印的是尺寸级别而非型号名称，因此每个型号对应到显示尺寸相符的级别。A80 与 A300 为户外防水机型。', 'เอกสารระบุระดับขนาด ไม่ได้ระบุชื่อรุ่น แต่ละรุ่นจึงแสดงเทียบกับระดับที่ขนาดจอตรงกัน A80 และ A300 เป็นรุ่นกันน้ำสำหรับกลางแจ้ง'],
