  'sz.model_P65': ['The commercial workhorse, and the class the sheet is built around.', '商業主力型號，也是表格主要依據的級別。', '商业主力型号，也是表格主要依据的级别。', 'รุ่นหลักงานพาณิชย์ และเป็นระดับที่ตารางอ้างอิง'],
  'sz.model_P80': ['The larger commercial fan, same class as the outdoor 80 cm unit.', '較大型商業風扇，與戶外 80 公分機型同一級別。', '较大型商业风扇，与户外 80 厘米机型同一级别。', 'พัดลมงานพาณิชย์ขนาดใหญ่ ระดับเดียวกับรุ่นกลางแจ้ง 80 ซม.'],
  'sz.model_A80': ['Outdoor waterproof unit; its 77 cm body matches the 80 cm class.', '戶外防水機型，77 公分機身對應 80 公分級別。', '户外防水机型，77 厘米机身对应 80 厘米级别。', 'รุ่นกันน้ำกลางแจ้ง ตัวเครื่อง 77 ซม. ตรงกับระดับ 80 ซม.'],
  'sz.model_A300': ['A 2.80 m unit — larger than this table covers. The sheet’s own line sends larger sizes to a technical solution, so this page does the same.', '2.80 公尺機型，超出本表涵蓋範圍。表格本身也把更大尺寸交由技術方案處理，本頁同樣如此。', '2.80 米机型，超出本表涵盖范围。表格本身也把更大尺寸交由技术方案处理，本页同样如此。', 'รุ่น 2.80 ม. ใหญ่เกินขอบเขตของตาราง เอกสารเองก็ให้ส่งขนาดที่ใหญ่กว่านี้ไปทำโซลูชันทางเทคนิค หน้านี้จึงทำเช่นเดียวกัน'],
