  'sz.r_maths': ['The arithmetic', '算式', '算式', 'สูตรคำนวณ'],
  'sz.capped': ['The table stops at 50 units (20.16 m in the 56 cm class, 35.79 m in the 100 cm class). Past that, the sheet asks for a technical solution — use the enquiry button below.', '表格最多列出 50 台（56 公分級別為 20.16 公尺，100 公分級別為 35.79 公尺）。超過此範圍，表格要求提供技術方案——請使用下方查詢按鈕。', '表格最多列出 50 台（56 厘米级别为 20.16 米，100 厘米级别为 35.79 米）。超出此范围，表格要求提供技术方案——请使用下方查询按钮。', 'ตารางสิ้นสุดที่ 50 เครื่อง (20.16 ม. ในระดับ 56 ซม. และ 35.79 ม. ในระดับ 100 ซม.) เกินกว่านั้นเอกสารให้ทำโซลูชันทางเทคนิค — ใช้ปุ่มสอบถามด้านล่าง'],
  'sz.preview_cap': ['{n} units in a row · {size} m', '一排 {n} 台 · {size} 公尺', '一排 {n} 台 · {size} 米', '{n} เครื่องเรียงแถว · {size} ม.'],
  'sz.table': ['The table, 1 to 50 units', '表格：1 至 50 台', '表格：1 至 50 台', 'ตาราง: 1 ถึง 50 เครื่อง'],
  'sz.table_lede': ['Every row of the source sheet, recalculated from the same two figures per class. The unit is metres.', '原始表格的每一列，依各級別的兩個數字重新計算。單位為公尺。', '原始表格的每一列，依各级别的两个数字重新计算。单位为米。', 'ทุกแถวของเอกสารต้นฉบับ คำนวณใหม่จากตัวเลขสองค่าของแต่ละระดับ หน่วยเป็นเมตร'],
  'sz.col_qty': ['Units', '台數', '台数', 'จำนวน'],
