  'dim.lede': ['Splicing several fans into one image depends on the model: each has a recommended centre-to-centre spacing. Enter the wall or stage size you want, or the number of units you have, and this page returns the build, the resolution, the power and the viewing distance. Figures use the manufacturer\'s calculation table.',
    '把多台風扇拼接成一個影像取決於型號：每個型號都有建議的中心距。輸入你想要的牆面或舞台尺寸，或你手上的台數，本頁會算出組合、解析度、電力及觀看距離。數字採用廠方的計算表。',
    '把多台风扇拼接成一个影像取决于型号：每个型号都有建议的中心距。输入你想要的墙面或舞台尺寸，或你手上的台数，本页会算出组合、分辨率、电力及观看距离。数字采用厂方的计算表。',
    'การนำพัดลมหลายเครื่องมาต่อเป็นภาพเดียวขึ้นกับรุ่น เพราะแต่ละรุ่นมีระยะห่างศูนย์กลางที่แนะนำ กรอกขนาดผนังหรือเวทีที่ต้องการ หรือจำนวนเครื่องที่มี หน้านี้จะคำนวณชุด ความละเอียด กำลังไฟ และระยะมอง ตัวเลขใช้ตารางคำนวณของผู้ผลิต'],
