  'dim.note': ['Spacing is set so images overlap into one picture. Going wider than the table leaves visible gaps; going tighter wastes brightness and units.',
    '中心距的設定是為了讓影像重疊成一張圖。比表格更闊會出現明顯縫隙；更密則浪費亮度及台數。',
    '中心距的设定是为了让影像重叠成一张图。比表格更宽会出现明显缝隙；更密则浪费亮度及台数。',
    'ระยะถูกตั้งให้ภาพซ้อนกันเป็นภาพเดียว หากกว้างกว่าตารางจะมีช่องว่าง หากแคบกว่าจะเสียความสว่างและเครื่อง'],
  'dim.formula': ['How it is worked out', '計算方式', '计算方式', 'วิธีคำนวณ'],
  'dim.f1': ['Columns and rows = the wall size divided by the spacing, rounded up.', '直列與橫排 = 牆面尺寸 ÷ 中心距，向上取整。', '直列与横排 = 墙面尺寸 ÷ 中心距，向上取整。', 'คอลัมน์และแถว = ขนาดผนัง ÷ ระยะห่าง ปัดขึ้น'],
  'dim.f2': ['Covered area = units × spacing², so it is slightly larger than the target.', '覆蓋面積 = 台數 × 中心距²，因此會略大於目標尺寸。', '覆盖面积 = 台数 × 中心距²，因此会略大于目标尺寸。', 'พื้นที่ครอบคลุม = จำนวนเครื่อง × ระยะ² จึงใหญ่กว่าเป้าเล็กน้อย'],
  'dim.f3': ['Fused resolution = per-unit resolution × the module that software fusion keeps.', '融合解析度 = 單台解析度 × 軟件融合保留的模組數。', '融合分辨率 = 单台分辨率 × 软件融合保留的模块数。', 'ความละเอียดรวม = ความละเอียดต่อเครื่อง × โมดูลที่ฟิวชันเก็บไว้'],
  'dim.f4': ['Power = units × rated watts, plus 20% headroom for the supply.', '電力 = 台數 × 額定瓦數，另加 20% 餘量。', '电力 = 台数 × 额定瓦数，另加 20% 余量。', 'กำลังไฟ = จำนวนเครื่อง × วัตต์ที่กำหนด บวกสำรอง 20%'],
  'dim.copy': ['Copy the build', '複製計算結果', '复制计算结果', 'คัดลอกผล'],
  'dim.copied': ['Build copied', '已複製', '已复制', 'คัดลอกแล้ว'],
  'dim.ask': ['Check this build with the team', '把這個組合交給團隊確認', '把这个组合交给团队确认', 'ให้ทีมตรวจชุดนี้'],
  'dim.empty': ['Enter a size or a unit count to see the build.', '輸入尺寸或台數以查看結果。', '输入尺寸或台数查看结果。', 'กรอกขนาดหรือจำนวนเครื่องเพื่อดูผล'],
  'dim.big': ['Over 30 units: talk to us about a project quote and rigging.', '超過 30 台：請與我們聯絡以取得專案報價及吊裝方案。', '超过 30 台：请与我们联系以取得项目报价及吊装方案。', 'เกิน 30 เครื่อง: คุยกับเราเรื่องใบเสนอราคาโครงการและริกกิ้ง'],

