  'cloud.what_1': ['Add, group, upgrade and monitor every device from one account.', '用一個帳戶新增、分組、升級及監控所有設備。', '用一个账户添加、分组、升级及监控所有设备。', 'เพิ่ม จัดกลุ่ม อัปเกรด และเฝ้าดูอุปกรณ์ทุกเครื่องจากบัญชีเดียว'],
